    "id": "scraped-c34b9ba056d6",
    "company": "Addis Ababa University College Of Health Sciences Aceps Project",
    "source": "EthioJobs",
    "title": "Call for PhD Candidates: FairChoices on the Path to Universal Health Coverage (UHC) in Times of Change (2026–2030)",
    "location": "Addis Ababa",
    "mode": "Onsite",
    "type": "Full-time Entry Level",
